#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Ticket 73's closing run: M5's exit from ticket 17, the Session checklist items
# (docs/testing/checklist.md) and the other items tagged M5, on the installed packages.
# The checks need four places, so the wizard has four parts, each with its own results:
#
#   73-closing-checks.sh tty     as caminitotest, beside `caminito --session` on a spare tty
#   73-closing-checks.sh dm      as yourself, in MATE on Caminito from the display manager
#   73-closing-checks.sh x11     as yourself, in X11 MATE, and then in MATE on Wayfire
#   73-closing-checks.sh nested  as yourself, on the host desktop, beside tools/dev-nested
#
# Run tty over ssh from another machine, which is best since the monitors stay on Caminito,
# or in a MATE Terminal inside the session, or from another tty. The session ends in
# tty's stage 6 and the machine powers off in dm's stage 3: a wizard that ends with
# them is run again and resumes. The results are saved as they're given. At the end
# they're appended to the ticket's notes when this copy can write them, and to a file to
# copy from otherwise: caminitotest can't read the developer's checkout, so it runs a copy.
#
# The nested and tty items of M1 to M4, 76's login on a tty and 60's hot-plug have
# wizards of their own, and each part's last stage says how to run them.

PART="${1:-}"
case $PART in
  tty) TOTAL_STAGES=7; WHERE="the login on a tty" ;;
  dm) TOTAL_STAGES=4; WHERE="the login from the display manager" ;;
  x11) TOTAL_STAGES=5; WHERE="X11 MATE and MATE on Wayfire" ;;
  nested) TOTAL_STAGES=4; WHERE="the nested items" ;;
  *)
    sed -n '/^# Ticket 73/,/^$/p' "$0" | sed 's/^# \{0,1\}//'
    exit 2 ;;
esac

HERE="$(dirname "$(realpath "$0")")"
TICKET="${TICKET:-$HERE/73-packaging-and-closing-m5.md}"
RESULTS=()   # "short name|pass, FAIL or not run|note"
FAILED=()
STATE="${XDG_STATE_HOME:-$HOME/.local/state}/caminito"
PROGRESS="$STATE/73-closing-checks-$PART.progress"
# The session the results are of: Caminito's pid, when it started and its command line.
SESSION="$STATE/73-closing-checks-$PART.session"
# Made when a stage asks for what ends the wizard's session, so a wizard run again goes on
# from there: tty's logout, dm's Shut Down (with the boot's id) and x11's Wayfire login.
ASKED="$STATE/73-closing-checks-$PART.asked"
LOG="${SESSION_LOG:-$HOME/session.log}"
DEBUG_CALL=(busctl --user call org.mate.Caminito.Debug /org/mate/Caminito/Debug org.mate.Caminito.Debug)
PACKAGES=(caminito-git mate-session-manager-caminito mate-panel-caminito mate-settings-daemon-caminito
  caja-caminito)
ROOT_PROPS=(_NET_SUPPORTED _NET_NUMBER_OF_DESKTOPS _NET_DESKTOP_NAMES _NET_CURRENT_DESKTOP
  _NET_WORKAREA _GTK_WORKAREAS_D0)
CAMINITO_PID=
SINCE=
COMMAND=
NESTED_WL=

# Every login of a user shares one runtime directory and session bus (14), so Caminito's are
# this login's. sudo and su don't set them.
export XDG_RUNTIME_DIR="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
export DBUS_SESSION_BUS_ADDRESS="${DBUS_SESSION_BUS_ADDRESS:-unix:path=$XDG_RUNTIME_DIR/bus}"

# session_environment prints what systemd's user manager has of a session's variables.
session_environment() {
  systemctl --user show-environment |
    grep -E '^(WAYLAND_DISPLAY|DISPLAY|MATE_WM_NAME|XDG_SESSION_TYPE|XDG_CURRENT_DESKTOP|XCURSOR_[A-Z]+)=' | sort || true
}
# in_session CMD... runs a command with the displays Caminito exported to systemd.
in_session() {
  # shellcheck disable=SC2046  # one NAME=value word per variable
  env $(systemctl --user show-environment | grep -E '^(WAYLAND_DISPLAY|DISPLAY)=') "$@"
}
# native CMD... starts a Wayland client in the session, detached.
native() { in_session env -u DISPLAY GDK_BACKEND=wayland setsid "$@" >/dev/null 2>&1 & }
# x11 CMD... starts an X11 client on the session's Xwayland, detached.
x11() { in_session env -u WAYLAND_DISPLAY GDK_BACKEND=x11 setsid "$@" >/dev/null 2>&1 & }
# show CMD... runs a command and shows it with its output, indented.
show() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@" 2>&1 | sed 's/^/    /' || true; }
# ok "..." prints a check that passed.
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
# running NAME succeeds when this user runs a process of that name.
running() { pgrep -u "$(id -u)" -x "$1" >/dev/null; }
# session_log prints what mate-session and what it starts wrote: the file Caminito's stderr
# goes to, which is the display manager's log of the session or the tty's file, and the
# journal.
session_log() {
  local stderr
  stderr=$(readlink /proc/"${CAMINITO_PID:-0}"/fd/2 2>/dev/null || true)
  [[ -f $stderr && -r $stderr && ! $stderr -ef $LOG ]] && sed 's/\x1b\[[0-9;]*m//g' "$stderr"
  [[ -r $LOG ]] && sed 's/\x1b\[[0-9;]*m//g' "$LOG"
  journalctl --user --since "$SINCE" -o cat --no-pager 2>/dev/null || true
}
# session_log_has TEXT succeeds when the session wrote TEXT. It counts, since grep -q
# closes the pipe at its first match, which pipefail makes a failure.
session_log_has() { [[ $(session_log | grep -c -- "$1" || true) -gt 0 ]]; }

# dump WHAT prints DumpState's outputs with their layer surfaces, or its windows.
dump() {
  local reply
  reply=$(in_session "${DEBUG_CALL[@]}" --json=short DumpState) || { warn "DumpState didn't answer"; return 0; }
  python3 -c '
import json, sys
state = json.loads(json.loads(sys.argv[2])["data"][0])
rect = lambda r: "%d,%d %dx%d" % (r["x"], r["y"], r["width"], r["height"]) if r else "unmapped"
if sys.argv[1] == "outputs":
    for o in state["outputs"]:
        print("%s: %s at scale %s, work area %s" % (o["name"], rect(o["geometry"]), o["scale"], rect(o["work_area"])))
        for s in o["layer_surfaces"]:
            print("  %-10s %-16s %s, zone %d" % (s["layer"], s["namespace"], rect(s["geometry"]), s["exclusive_zone"]))
else:
    for w in state["windows"]:
        print("%s %r: %s" % ("X11   " if w["xwayland"] else "native", w["title"], rect(w["geometry"])))
' "$1" "$reply" | sed 's/^/    /' || warn "DumpState's reply couldn't be read"
}

# find_session finds the Caminito that runs the session, and waits for its export.
find_session() {
  local exe _
  while true; do
    CAMINITO_PID=$(pgrep -n -x -u "$(id -u)" caminito || true)
    if [[ -n $CAMINITO_PID ]] && tr '\0' ' ' < /proc/"$CAMINITO_PID"/cmdline | grep -q -- '--session'; then
      for _ in $(seq 30); do
        session_environment | grep -q '^WAYLAND_DISPLAY=' && break 2
        sleep 1
      done
      warn "caminito (pid $CAMINITO_PID) exported no WAYLAND_DISPLAY to systemd in 30 s"
    else
      warn "no caminito --session of $(id -un) is running"
    fi
    if [[ $PART == tty ]]; then
      step "Log in as caminitotest on a spare tty (Ctrl+Alt+F4, for example), and run:"
      step "caminito --session 2>~/session.log; echo \"caminito exited with \$?\""
    else
      step "Log out of every session of yours, and log into MATE on Caminito at the greeter."
      step "Then run this wizard again in a MATE Terminal there, and resume."
    fi
    pause "Press Enter once the desktop is up"
  done
  # Caminito may have gone since the search: the stage's checks then say so.
  SINCE=$(date -d "$(ps -o lstart= -p "$CAMINITO_PID" || true)" '+%F %T')
  COMMAND=$(tr '\0' ' ' 2>/dev/null < /proc/"$CAMINITO_PID"/cmdline | sed 's/ $//' || true)
  printf '%s\n%s\n%s\n' "$CAMINITO_PID" "$SINCE" "$COMMAND" > "$SESSION"
  ok "caminito is pid $CAMINITO_PID, started at $SINCE as: $COMMAND"
  exe=$(readlink /proc/"$CAMINITO_PID"/exe 2>/dev/null || true)
  [[ -z $exe || $exe == /usr/bin/caminito ]] || warn "it's $exe, not the installed /usr/bin/caminito"
}
# session_runs succeeds while the Caminito a stage found runs. A pid a stopped run saved may
# be another process's by now, after a restart of the machine.
session_runs() {
  [[ -n $CAMINITO_PID && $(cat /proc/"$CAMINITO_PID"/comm 2>/dev/null || true) == caminito ]]
}
# need_session finds the session unless the one a stage found before still runs.
need_session() {
  session_runs || find_session
}
# load_session reads back the session a stopped run found, which may have ended since.
load_session() {
  [[ -s $SESSION ]] || return 0
  { read -r CAMINITO_PID; read -r SINCE; read -r COMMAND; } < "$SESSION" || true
}
# await_exit waits for the session's Caminito to be gone.
await_exit() {
  while session_runs; do
    warn "caminito (pid $CAMINITO_PID) is still running"
    pause "Press Enter once the session has ended"
  done
}
# session_checks shows what a login's commands say: the processes, the export, the time-outs
# and the layer surfaces. The eyes' part is the stage's.
session_checks() {
  local process parent name
  for process in mate-session mate-panel caja mate-settings-daemon; do
    if pgrep -u "$(id -u)" -f "(^|/)$process( |\$)" >/dev/null; then ok "$process runs"; else warn "$process isn't running"; fi
  done
  parent=$(ps -o ppid= -p "$(pgrep -o -x -u "$(id -u)" mate-session || echo 0)" 2>/dev/null | tr -d ' ' || true)
  if [[ $parent == "$CAMINITO_PID" ]]; then ok "mate-session is Caminito's child"; else warn "mate-session's parent is pid ${parent:-(none)}, and Caminito is pid $CAMINITO_PID"; fi
  show session_environment
  for name in WAYLAND_DISPLAY DISPLAY; do
    if session_environment | grep -q "^$name="; then ok "$name is there"; else warn "$name is missing"; fi
  done
  if session_environment | grep -qx 'MATE_WM_NAME=Caminito'; then ok "MATE_WM_NAME=Caminito is there"; else warn "MATE_WM_NAME=Caminito is missing"; fi
  say "Time-outs, in what the session wrote:"
  TIMEOUTS=$(session_log | grep -iE 'timed out|time-?out' | sort | uniq -c || true)
  if [[ -n $TIMEOUTS ]]; then sed 's/^/    /' <<< "$TIMEOUTS"; else ok "none"; fi
  say "DumpState's outputs and their layer surfaces:"
  dump outputs
}

# record NAME VERDICT NOTE saves a result as it's given.
record() {
  RESULTS+=("$1|$2|$3")
  printf '%s|%s|%s\n' "$1" "$2" "$3" >> "$PROGRESS"
  if [[ $2 == FAIL ]]; then FAILED+=("$1"); fi
}
# result "Short name" records whether the check passed, failed or wasn't run, with
# an optional note.
result() {
  local name="$1" reply="" verdict note=""
  printf '  %s? Did all of it work? (%s) [y]es, [n]o, [s]kipped:%s ' "$YELLOW" "$name" "$RESET"
  read -r reply || true
  case $reply in
    [Yy]*) verdict=pass ;;
    [Ss]*) verdict="not run" ;;
    *) verdict=FAIL ;;
  esac
  printf '  %sNote (what you saw; Enter for none):%s ' "$BOLD" "$RESET"
  read -r note || true
  record "$name" "$verdict" "$note"
}

# start_over forgets a stopped run.
start_over() {
  rm -f "$PROGRESS" "$SESSION" "$ASKED"
}
# load_progress offers to resume from the results a stopped run saved.
load_progress() {
  local r name verdict note
  mkdir -p "$STATE"
  [[ -s $PROGRESS ]] || { start_over; return 0; }
  say "A stopped run saved these results:"
  while IFS= read -r r; do
    IFS='|' read -r name verdict note <<< "$r"
    say "  $verdict  $name${note:+ ($note)}"
  done < "$PROGRESS"
  if confirm "Resume, skipping the stages they cover? (No starts over)"; then
    mapfile -t RESULTS < "$PROGRESS"
    for r in "${RESULTS[@]}"; do
      IFS='|' read -r name verdict _ <<< "$r"
      if [[ $verdict == FAIL ]]; then FAILED+=("$name"); fi
    done
    load_session
  else
    start_over
  fi
}

# recorded NAME succeeds when NAME's result is recorded.
recorded() {
  local r
  for r in ${RESULTS[@]+"${RESULTS[@]}"}; do [[ $r == "$1|"* ]] && return 0; done
  return 1
}
# done_already NAME succeeds, and says so, when NAME's result is recorded.
done_already() {
  recorded "$1" || return 1
  say "Already recorded; skipping."
  sleep 1
}

# write_results appends the results to the ticket's notes. caminitotest can't write
# the developer's checkout, so from there they go to a file to copy from.
write_results() {
  local r name verdict note target="$TICKET"
  [[ -w $target ]] || target="$STATE/73-closing-results.md"
  printf '\n- **Closing run, %s (%s), as %s on %s (%s), on %s:**\n' \
    "$WHERE" "$(date +%F)" "$(id -un)" "$(uname -n)" "$(uname -m)" \
    "$(pacman -Q "${PACKAGES[@]}" 2>&1 | paste -sd, | sed 's/,/, /g')" >> "$target"
  for r in "${RESULTS[@]}"; do
    IFS='|' read -r name verdict note <<< "$r"
    printf '  - %s: %s.%s\n' "$name" "$verdict" "${note:+ $note}" >> "$target"
  done
  printf '  %s✓ wrote%s %s results to %s\n' "$GREEN" "$RESET" "${#RESULTS[@]}" "$target"
  [[ $target == "$TICKET" ]] ||
    SKIPPED+=("copying $target into ticket 73's notes")
}
# record_stage is each part's last stage: it shows the results, writes them down, and
# lists what the closing still needs.
record_stage() {
  local r name verdict note other others=""
  stage "Record the results"
  for r in ${RESULTS[@]+"${RESULTS[@]}"}; do
    IFS='|' read -r name verdict note <<< "$r"
    say "$verdict  $name${note:+ ($note)}"
  done
  if confirm "Write these down?"; then
    write_results
    rm -f "$PROGRESS" "$SESSION" "$ASKED"
    (( ${#FAILED[@]} )) && SKIPPED+=("a new ticket for each failure, before M5 closes: ${FAILED[*]}")
  else
    SKIPPED+=("recording the results in ticket 73 (they stay in $PROGRESS)")
  fi
  for other in tty dm x11 nested; do
    [[ $other == "$PART" ]] || others+=" $other"
  done
  SKIPPED+=("this wizard's other parts, unless they're in 73's notes already:  73-closing-checks.sh <one of$others>")
  SKIPPED+=("the nested M1 to M4 items, on the host desktop with tools/dev-nested (no --bin), from the checkout's issues directory:  TICKET=\$PWD/73-packaging-and-closing-m5.md ./43-closing-checks.sh  and the same for ./54-hand-checks.sh")
  SKIPPED+=("the tty items of M4, as caminitotest beside bare caminito:  59-closing-checks.sh, whose results go to a file to copy into 73's notes")
  SKIPPED+=("76's login on a tty (76-checks/tty-login.sh) and 60's hot-plug, if they're still open")
  SKIPPED+=("a push, with CI and the Packaging job green, before the Close M5 MATE session commit")
  pause
  finish
}

banner "Ticket 73: closing M5, $WHERE"
load_progress

case $PART in
# ══ tty ═══════════════════════════════════════════════════════════════════
tty)

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before the checks"
[[ $(id -un) == caminitotest ]] || warn "this is $(id -un), not caminitotest, the second user (14)"
show pacman -Q "${PACKAGES[@]}"
for tool in busctl gsettings python3 pluma xprop wayland-info loginctl journalctl; do
  command -v "$tool" >/dev/null || warn "$tool is missing"
done
say "The session runs as caminitotest on a spare tty, with Caminito's stderr in a file, so"
say "that Caminito logs to the journal, and with its exit status shown afterwards:"
step "caminito --session 2>~/session.log; echo \"caminito exited with \$?\""
# A run that already asked for the logout has no session to find.
if [[ -e $ASKED ]]; then
  say "This run already asked for the logout; going on from there."
  sleep 1
else
  need_session
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "M5's exit: MATE on Caminito starts mate-session, on a tty"
if ! done_already "As caminitotest on a tty, MATE on Caminito starts mate-session, the panel, caja's desktop and msd"; then
need_session
session_checks
show loginctl list-sessions --no-pager
step "The desktop came up well inside 30 seconds."
step "mate-panel shows the window list and the workspace switcher: open a window, and its"
step "button is there; click another workspace in the switcher, and come back."
step "caja draws the desktop icons (Computer, Home, Trash), on one output (06)."
step "msd's wallpaper is under them, and alone on the other output."
note "Expected: a mate-background surface in background on every output, caja's desktop"
note "in bottom on one, and the two panels with their exclusive zones."
result "As caminitotest on a tty, MATE on Caminito starts mate-session, the panel, caja's desktop and msd"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Checklist: DISPLAY only exported after the root properties exist"
if ! done_already "DISPLAY only exported after the root properties exist"; then
need_session
MS_PID=$(pgrep -o -x -u "$(id -u)" mate-session || true)
MS_DISPLAY=$(tr '\0' '\n' 2>/dev/null < /proc/"${MS_PID:-0}"/environ | sed -n 's/^DISPLAY=//p' || true)
say "mate-session (pid ${MS_PID:-none}) was given DISPLAY=${MS_DISPLAY:-(none)}"
show sh -c "journalctl --user --since '$SINCE' -t caminito -o cat --no-pager | sed 's/\x1b\[[0-9;]*m//g' | grep -E 'Xwayland is ready|started the session command'"
show env DISPLAY="${MS_DISPLAY:-:0}" xprop -root "${ROOT_PROPS[@]}"
note "Expected (38): mate-session's DISPLAY is the one in 'Xwayland is ready on DISPLAY=',"
note "which is logged before 'started the session command'. _NET_SUPPORTED has the desktop"
note "atoms, _NET_WORKAREA and _GTK_WORKAREAS; the desktops are as in org.mate.Marco.general,"
note "with a work area for each."
result "DISPLAY only exported after the root properties exist"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Checklist: an X11 app's clipboard contents survive the app quitting"
if ! done_already "An X11 app's clipboard contents survive the app quitting"; then
need_session
show in_session sh -c 'wayland-info | grep data_control'
if session_log_has 'does not support the ext-data-control protocol'; then
  warn "msd logged that the compositor does not support the ext-data-control protocol"
else
  ok "msd didn't log that ext-data-control is missing"
fi
if running pluma; then warn "pluma is running: quit it first, since it hands a new window to the running one"; pause; fi
say "Opening pluma on Xwayland."
x11 pluma
step "Type a line, select it, copy it with Ctrl+C, and quit pluma."
pause "Press Enter once pluma is closed"
say "Waiting 5 seconds: msd takes the selection about 2 seconds after its owner goes (71)."
sleep 5
if command -v wl-paste >/dev/null; then show in_session wl-paste --no-newline; fi
say "Opening pluma on Wayland."
native pluma
step "Paste with Ctrl+V: the line is there. Quit pluma."
pause "Press Enter once pluma is closed"
say "Opening pluma on Xwayland again."
x11 pluma
step "Paste with Ctrl+V: the line is there too. Quit pluma."
note "Expected (11, 68): both paste the line, though the app that owned it is gone."
result "An X11 app's clipboard contents survive the app quitting"
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Checklist: Shut Down from the panel, cancelled"
if ! done_already "Shut Down shows mate-session's dialog"; then
need_session
step "In the panel: System, Shut Down…"
step "The dialog asks 'Shut down this system now?' and counts down. It has a frame"
step "drawn by Caminito, like any XWayland window."
step "Cancel it: the session goes on as it was."
note "Expected (70): mate-session's dialog, and not the panel's own, which is titled"
note "'System Shutdown'. Shutting down for real is the dm part's, as yourself."
result "Shut Down shows mate-session's dialog"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "M5's exit: logging out through the panel"
if ! done_already "Log Out ends the session, and Caminito exits with mate-session's status"; then
if [[ ! -e $ASKED ]]; then
  need_session
  say "Before the logout:"
  show session_environment
  : > "$ASKED"
  step "In the panel: System, Log Out caminitotest…, then Log Out."
  warn "A wizard inside the session ends with it. Run it again from the tty and resume."
  pause "Press Enter once the session has ended"
fi
await_exit
if pgrep -x -u "$(id -u)" caminito >/dev/null; then
  warn "a new caminito runs already, so the environment below is its, not what the logout left"
fi
show session_environment
UNSET=$(journalctl --user --since "$SINCE" -t caminito -o cat --no-pager 2>/dev/null | grep -c "didn't unset the environment" || true)
say "Caminito logged 'systemd didn't unset the environment' $UNSET times."
show sh -c "journalctl --user --since '$SINCE' -t caminito -o cat --no-pager | sed 's/\x1b\[[0-9;]*m//g' | grep 'the session command exited'"
say "What is left of the session:"
pgrep -u "$(id -u)" -a | grep -vE 'systemd|\(sd-pam\)|dbus-(daemon|broker)|pgrep|sshd|bash|login|closing-checks' | sed 's/^/    /' || ok "nothing"
step "Caminito's tty is back in text mode, at the shell prompt, which printed"
step "'caminito exited with 0': say in the note if it printed another status."
note "Expected (61, 74): Caminito exits with mate-session's status, which is 0 after a Log"
note "Out, and of the session's variables only XDG_CURRENT_DESKTOP and XDG_SESSION_TYPE stay."
result "Log Out ends the session, and Caminito exits with mate-session's status"
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
record_stage
;;

# ══ dm ════════════════════════════════════════════════════════════════════
dm)

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before the checks"
[[ $(id -un) != caminitotest ]] || warn "this is caminitotest: the login from the display manager is as yourself (72)"
show pacman -Q "${PACKAGES[@]}"
show pacman -Qo /usr/share/wayland-sessions/mate-caminito.desktop
show systemctl is-active display-manager.service
command -v wlr-randr >/dev/null || warn "wlr-randr is missing"
say "Log out of every session of yours first: its logins share one systemd manager and"
say "bus, and the session changes both (14). The session can't lock until M7 (62)."
if [[ -e $ASKED ]]; then
  say "This run already asked for the Shut Down; going on from there."
  sleep 1
else
  need_session
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "M5's exit: MATE on Caminito starts mate-session, from the display manager"
if ! done_already "From the display manager, MATE on Caminito starts mate-session, the panel, caja's desktop and msd"; then
need_session
session_checks
show loginctl show-session "${XDG_SESSION_ID:-auto}" -p Type -p Class -p Service -p Desktop -p TTY
say "Caminito's stderr is $(readlink /proc/"$CAMINITO_PID"/fd/2 2>/dev/null || echo '(unreadable)')"
say "journalctl --user -t caminito: $(journalctl --user --since "$SINCE" -t caminito -o cat --no-pager 2>/dev/null | wc -l) lines"
say "Caminito's warnings and errors:"
journalctl --user --since "$SINCE" -t caminito -p warning -o cat --no-pager 2>/dev/null |
  sed 's/\x1b\[[0-9;]*m//g' | sort | uniq -c | head -n 20 | sed 's/^/    /' || true
step "The greeter's session list had MATE on Caminito."
step "The desktop came up well inside 30 seconds, with both panels, the window list and"
step "the workspace switcher, caja's icons, and msd's wallpaper on every output."
say "The outputs, which Caminito put where its saved layout or its defaults have them (83):"
show in_session sh -c "wlr-randr | grep -E '^[^ ]|Position|Scale|current'"
note "Expected: a logind session of type wayland, and Caminito's lines in the journal,"
note "since its stderr isn't a terminal (14)."
result "From the display manager, MATE on Caminito starts mate-session, the panel, caja's desktop and msd"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Checklist: Shut Down from the panel"
if ! done_already "Shut Down powers the machine off"; then
BOOT=$(cat /proc/sys/kernel/random/boot_id)
# A run stopped before the Shut Down, and resumed in the same boot, asks again.
if [[ ! -e $ASKED || $(cat "$ASKED") == "$BOOT" ]]; then
  printf '%s\n' "$BOOT" > "$ASKED"
  sync
  step "Save your work. In the panel: System, Shut Down…, then Shut Down."
  step "mate-session's dialog shows first, and the machine powers off."
  step "Start it again, log in as you like, and run this wizard again:  $0 dm"
  note "To leave this for later, press Ctrl-C now: a run again resumes here."
  pause "Press Enter only if the machine didn't power off"
fi
if [[ $(cat "$ASKED") == "$BOOT" ]]; then
  warn "this is the boot the Shut Down was asked in: the machine didn't power off"
else
  # By its id, since the machine may have been started more than once since.
  ASKED_BOOT=$(tr -d - < "$ASKED")
  ok "the machine was started again since the Shut Down was asked for"
  say "The end of Caminito's journal in the boot it was asked in:"
  show sh -c "journalctl --user -b $ASKED_BOOT -t caminito -o cat --no-pager | sed 's/\x1b\[[0-9;]*m//g' | tail -n 8"
  UNSET=$(journalctl --user -b "$ASKED_BOOT" -t caminito -o cat --no-pager 2>/dev/null | grep -c "didn't unset the environment" || true)
  say "Caminito logged 'systemd didn't unset the environment' $UNSET times in that boot: a"
  say "systemd that's shutting down may not answer (61)."
  warn "Answer no if the machine was started again for another reason than the Shut Down."
fi
note "Expected (08, 70): mate-session's 'Shut down this system now?' dialog, the session"
note "ending as at a Log Out ('the session command exited' in that boot's journal), and"
note "the machine powering off."
result "Shut Down powers the machine off"
rm -f "$ASKED"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
record_stage
;;

# ══ x11 ═══════════════════════════════════════════════════════════════════
x11)

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before the checks"
[[ $(id -un) != caminitotest ]] || warn "this is caminitotest: the fall-back rule is checked on your own user"
show pacman -Q mate-session-manager mate-panel mate-settings-daemon caja
for package in "${PACKAGES[@]:1}"; do
  pacman -Q "$package" >/dev/null 2>&1 || warn "$package isn't installed, so this wouldn't check the Patched packages"
done
if [[ -e $ASKED ]]; then
  say "This run already asked for the Wayfire login; going on from there."
  sleep 1
elif [[ ${XDG_SESSION_TYPE:-} != x11 ]] || ! running marco; then
  warn "this isn't X11 MATE (XDG_SESSION_TYPE=${XDG_SESSION_TYPE:-unset}, and marco $(running marco && echo runs || echo "doesn't run"))"
  step "Log into MATE, the X11 session, from the display manager, and run this there."
  pause "Press Enter to go on anyway"
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Checklist: X11 MATE with the Patched packages, by its commands"
if ! done_already "X11 MATE is unchanged with the Patched packages: what the commands say"; then
say "XDG_SESSION_TYPE=${XDG_SESSION_TYPE:-unset} MATE_WM_NAME=${MATE_WM_NAME:-unset} GDK_BACKEND=${GDK_BACKEND:-unset}"
if running marco; then ok "marco runs, started by mate-session"; else warn "marco isn't running"; fi
if busctl --user status org.mate.Caminito >/dev/null 2>&1; then warn "org.mate.Caminito has an owner"; else ok "nothing owns org.mate.Caminito"; fi
GNOME_BEFORE=$(gsettings get org.gnome.desktop.interface gtk-theme 2>&1 || true)
THEME=$(gsettings get org.mate.interface gtk-theme | tr -d "'" || true)
OTHER=TraditionalOk
[[ $THEME != "$OTHER" ]] || OTHER=Menta
say "Changing MATE's theme from $THEME to $OTHER: look at the open windows."
# A wizard stopped before the pause's Enter still puts the theme back.
trap 'gsettings set org.mate.interface gtk-theme "$THEME" || true' EXIT
show gsettings set org.mate.interface gtk-theme "$OTHER"
sleep 3
GNOME_AFTER=$(gsettings get org.gnome.desktop.interface gtk-theme 2>&1 || true)
if [[ $GNOME_BEFORE == "$GNOME_AFTER" ]]; then
  ok "org.gnome.desktop.interface gtk-theme stayed $GNOME_AFTER: msd doesn't mirror here"
else
  warn "org.gnome.desktop.interface gtk-theme went from $GNOME_BEFORE to $GNOME_AFTER: msd mirrored it"
  gsettings set org.gnome.desktop.interface gtk-theme "$(tr -d "'" <<< "$GNOME_BEFORE")" || true
fi
step "The open windows redrew in $OTHER, so msd serves XSETTINGS as stock."
pause "Press Enter to put $THEME back"
gsettings set org.mate.interface gtk-theme "$THEME" || true
trap - EXIT
say "Applets whose libraries aren't there, of those installed (70):"
BROKEN=0
while IFS= read -r applet; do
  [[ -x $applet ]] || continue
  # Counted, not grep -q: see session_log_has.
  if [[ $(ldd "$applet" 2>/dev/null | grep -c 'not found' || true) -gt 0 ]]; then
    BROKEN=$((BROKEN + 1))
    printf '    %s (%s): %s\n' "$applet" "$(pacman -Qqo "$applet" 2>/dev/null || echo '?')" \
      "$(ldd "$applet" | sed -n 's/^\s*\(\S*\) => not found/\1/p' | paste -sd' ')"
  fi
done < <(grep -h '^Location=' /usr/share/mate-panel/applets/*.mate-panel-applet | cut -d= -f2 | sort -u)
if (( BROKEN )); then
  warn "$BROKEN applets can't start. One that misses libmate-panel-applet-4.so.1 is the"
  warn "patched panel's doing (70); another library was missing with the stock panel too."
else
  ok "none"
fi
say "Applets loaded into the panel's process and linked to the 1.28 library, which can't"
say "work there beside master's (73):"
INSIDE=$(grep -l '^InProcess=true' /usr/share/mate-panel/applets/*.mate-panel-applet | xargs -r grep -h '^Location=' | cut -d= -f2 |
  while IFS= read -r applet; do
    [[ $(ldd "$applet" 2>/dev/null | grep -c 'libmate-panel-applet-4\.so\.1 ' || true) -gt 0 ]] && printf '    %s\n' "$applet"
  done || true)
if [[ -n $INSIDE ]]; then printf '%s\n' "$INSIDE"; note "One of these on a panel is a failure; installed and unused, it's the known gap."; else ok "none"; fi
say "The applets on your panels:"
dconf dump /org/mate/panel/objects/ | sed -n "s/^applet-iid='\(.*\)'/    \1/p" | sort | uniq -c || true
note "Expected (ADR 0011): x11, with MATE_WM_NAME and GDK_BACKEND as they were with the"
note "stock packages, Marco running, no mirror, and no applet missing the panel's library."
result "X11 MATE is unchanged with the Patched packages: what the commands say"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Checklist: X11 MATE with the Patched packages, by hand"
if ! done_already "X11 MATE is unchanged with the Patched packages: the panel"; then
step "Every applet that was on your panels before is there, and works."
step "Add an applet of another package to a panel (Command or Trash, of mate-applets): it"
step "shows and works, on the 1.28 library (73). Take it off again."
step "A window list button focuses its window, minimises it, and brings it back, with"
step "Marco's minimise animation going to the button."
step "The workspace switcher switches, and shows the windows of each workspace."
step "System, Log Out…  shows mate-session's dialog: cancel it."
step "System, Shut Down…  shows mate-session's dialog: cancel it."
step "Say in the note whether the countdown's bar sits as close to the buttons as in the Session."
step "The wallpaper and the desktop icons are caja's, as before."
show sh -c "grep -aiE 'mate-panel|applet' ~/.xsession-errors 2>/dev/null | tail -n 8"
note "Expected: all of it as with the stock packages."
result "X11 MATE is unchanged with the Patched packages: the panel"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Checklist: MATE on Wayfire with the Patched packages"
if ! done_already "MATE on Wayfire is unchanged with the Patched packages"; then
if [[ ! -e /usr/share/wayland-sessions/MATE.desktop ]]; then
  warn "mate-wayland-session isn't installed"
  record "MATE on Wayfire is unchanged with the Patched packages" "not run" "mate-wayland-session isn't installed."
else
  if [[ ! -e $ASKED ]]; then
    : > "$ASKED"
    step "Log out, and log into MATE on Wayfire from the display manager."
    step "Run this wizard again in a terminal there, and resume:  $0 x11"
    exit 0
  fi
  say "XDG_SESSION_TYPE=${XDG_SESSION_TYPE:-unset} MATE_WM_NAME=${MATE_WM_NAME:-unset} GDK_BACKEND=${GDK_BACKEND:-unset}"
  if running wayfire; then ok "wayfire runs"; else warn "wayfire isn't running: is this MATE on Wayfire?"; fi
  if busctl --user status org.mate.Caminito >/dev/null 2>&1; then warn "org.mate.Caminito has an owner"; else ok "nothing owns org.mate.Caminito"; fi
  for process in mate-panel mate-settings-daemon; do
    if pgrep -u "$(id -u)" -f "(^|/)$process( |\$)" >/dev/null; then ok "$process runs"; else warn "$process isn't running"; fi
  done
  step "The panel, its window list, the desktop icons and the wallpaper are as they were"
  step "with the stock packages (81). Leave with Super+Escape (wlogout) or pkill wayfire:"
  step "the panel's Log Out does nothing there, stock or patched, with no mate-session."
  note "Expected (ADR 0011): a patch that turns on under Wayfire is a bug. The panel's own"
  note "patches aren't gated: it tells Wayfire where each button is, and Shut Down goes"
  note "through the session manager when there is one."
  result "MATE on Wayfire is unchanged with the Patched packages"
  rm -f "$ASKED"
fi
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
record_stage
;;

# ══ nested ════════════════════════════════════════════════════════════════
nested)

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before the checks"
say "Run this on the host desktop, from the checkout."
show pacman -Q caminito-git
for tool in wl-copy wl-paste wayland-info flatpak; do
  command -v "$tool" >/dev/null || warn "$tool is missing"
done
step "In a second terminal, from the checkout, run:  tools/dev-nested"
step "No --bin: these checks are on the installed package."
while true; do
  printf '  %sPaste the line "dev-nested: WAYLAND_DISPLAY=… DISPLAY=:…":%s ' "$BOLD" "$RESET"
  read -r line || true
  if [[ $line =~ WAYLAND_DISPLAY=(wayland-[0-9]+) ]]; then NESTED_WL=${BASH_REMATCH[1]}; break; fi
  warn "that isn't the dev-nested line; try again"
done
ok "nested WAYLAND_DISPLAY=$NESTED_WL"
export WAYLAND_DISPLAY="$NESTED_WL"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Checklist: a clipboard watcher sees each copy without a window"
if ! done_already "A clipboard watcher sees each copy without a window"; then
show sh -c 'wayland-info | grep data_control'
WATCHED="$STATE/73-watched"
timeout 8 wl-paste --watch sh -c 'cat; echo' > "$WATCHED" 2>&1 &
sleep 1
wl-copy first || true
sleep 2
wl-copy second || true
sleep 2
say "What wl-paste --watch, a data-control client with no window, printed:"
sed 's/^/    /' "$WATCHED" || true
wait || true
wl-copy --clear || true
note "Expected (68): first, then second, as each is copied."
result "A clipboard watcher sees each copy without a window"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Checklist: a Flatpak app's sandbox is offered no privileged global"
if ! done_already "A Flatpak app's sandbox is offered no privileged global"; then
RUNTIME=$(flatpak list --runtime --columns=ref 2>/dev/null | grep -m1 '^org.freedesktop.Platform/' || true)
if [[ -z $RUNTIME ]]; then
  warn "no org.freedesktop.Platform runtime is installed"
  record "A Flatpak app's sandbox is offered no privileged global" "not run" "No Flatpak runtime is installed."
else
  globals() { sed -n "s/^interface: '\([^']*\)'.*/\1/p" | sort; }
  wayland-info | globals > "$STATE/73-globals-outside" || warn "wayland-info failed: does the nested Caminito still run?"
  flatpak run --socket=wayland --filesystem=host-os:ro \
    --command=/run/host/usr/bin/wayland-info "$RUNTIME" 2>&1 | globals > "$STATE/73-globals-inside" ||
    warn "wayland-info failed in the sandbox"
  say "Outside the sandbox: $(wc -l < "$STATE/73-globals-outside") globals. Inside $RUNTIME: $(wc -l < "$STATE/73-globals-inside")."
  say "The ones the sandbox isn't offered:"
  comm -23 "$STATE/73-globals-outside" "$STATE/73-globals-inside" | sed 's/^/    /'
  show grep -E '^(xdg_wm_base|wl_data_device_manager)$' "$STATE/73-globals-inside"
  note "Expected (68, 75): nine fewer inside, which are zwlr_layer_shell_v1,"
  note "zwlr_foreign_toplevel_manager_v1, xfce_foreign_toplevel_manager_private_v1,"
  note "ext_foreign_toplevel_list_v1, ext_workspace_manager_v1, zwlr_output_manager_v1,"
  note "ext_data_control_manager_v1, zwlr_data_control_manager_v1 and"
  note "wp_security_context_manager_v1. xdg_wm_base and wl_data_device_manager are inside."
  result "A Flatpak app's sandbox is offered no privileged global"
fi
fi
step "Quit the nested Caminito."

# ── 4 ─────────────────────────────────────────────────────────────────────
record_stage
;;
esac
